mapper.select:
SELECT pay_id as payId, username, gym_id as gymId, installment, pay_price as payPrice, pay_date as payDate, pay_name as payName, data_id as dataId FROM "h_payment" WHERE gym_id = (SELECT gym_id FROM "h_member" WHERE username = #{username})
AND TO_CHAR(pay_date, 'YYYY-MM') = #{pager.month}
AND (pay_name LIKE CONCAT('%', #{pager.searchKeyword}, '%') OR CAST(username AS TEXT) LIKE CONCAT('%', #{pager.searchKeyword}, '%'))
ORDER BY pay_id DESC LIMIT #{pager.pageSize} OFFSET #{pager.offset}

SELECT COUNT(*) FROM "h_payment" WHERE gym_id = (SELECT gym_id FROM "h_member" WHERE username = #{username})
AND TO_CHAR(pay_date, 'YYYY-MM') = #{pager.month}
AND (pay_name LIKE CONCAT('%', #{pager.searchKeyword}, '%') OR CAST(username AS TEXT) LIKE CONCAT('%', #{pager.searchKeyword}, '%'))

SELECT COALESCE(SUM(pay_price), 0) FROM "h_payment" WHERE gym_id = (SELECT gym_id FROM "h_member" WHERE username = #{username})
AND TO_CHAR(pay_date, 'YYYY-MM') = #{pager.month}
AND (pay_name LIKE CONCAT('%', #{pager.searchKeyword}, '%') OR CAST(username AS TEXT) LIKE CONCAT('%', #{pager.searchKeyword}, '%'))

SELECT s.settlement_id as settlementId, s.gym_id as gymId, g.gym_name as gymName, s.commission, s.settled_at as settledAt, s.commission_rate as commissionRate, s.settle_month as settleMonth, s.status, s.expense_id as expenseId FROM "h_settlement" s LEFT JOIN "h_gym" g ON s.gym_id = g.gym_id
AND s.status = #{pager.searchKeyword}
AND TO_CHAR(s.settle_month, 'YYYY-MM') = #{pager.month}
ORDER BY s.settlement_id DESC LIMIT #{pager.pageSize} OFFSET #{pager.offset}

SELECT COUNT(*)
FROM "h_settlement" s


        AND s.status = #{pager.searchKeyword}


        AND TO_CHAR(s.settle_month, 'YYYY-MM') = #{pager.month}

mapper.update:
UPDATE "h_settlement"
SET status = #{status},
    settled_at = #{settledAt}
WHERE settlement_id = #{settlementId}

